```julia
function insertion_sort!(v::AbstractVector; lt = isless)
    for i in firstindex(v)+1:lastindex(v)
        x = v[i]
        j = i - 1
        while j >= firstindex(v) && lt(x, v[j])
            v[j+1] = v[j]
            j -= 1
        end
        v[j+1] = x
    end
    return v
end

# Checks
@assert insertion_sort!([3, 1, 2]) == [1, 2, 3]
@assert insertion_sort!(["pear", "apple", "fig"]) == ["apple", "fig", "pear"]
@assert insertion_sort!([3, 1, 2]; lt = >) == [3, 2, 1]
w = rand(50)
@assert insertion_sort!(copy(w)) == sort(w)
```

Indexing goes through `firstindex`/`lastindex`, so the function also works on offset arrays and views, and `lt` lets callers choose the order. Insertion sort is O(n^2) in the worst case but O(n) on nearly sorted input and stable, which is why it is still used for small ranges inside library sorts. For real work call `sort!`.

```julia
contains_sorted(v::AbstractVector, x) = (i = searchsortedfirst(v, x); i <= lastindex(v) && isequal(v[i], x))

insertion_point(v::AbstractVector, x) = searchsortedfirst(v, x)

# Checks
v = [1, 3, 5, 7, 9]
@assert contains_sorted(v, 7)
@assert !contains_sorted(Int[], 1)
@assert insertion_point(v, 4) == 3
@assert insertion_point(v, 100) == 6
```

`searchsortedfirst` is the Base binary search: it returns the first index whose element is not less than `x`, so membership is one comparison afterwards. Both calls are O(log n). The vector must already be sorted under the same ordering; pass `by=` or `lt=` to the search if you sorted with them.

```julia
function count_in_range(v::AbstractVector, lo, hi)
    lo <= hi || throw(ArgumentError("lo ($lo) must not exceed hi ($hi)"))
    return length(searchsortedfirst(v, lo):searchsortedlast(v, hi))
end

# Checks
v = [1, 2, 2, 4, 7, 7, 7, 10]
@assert count_in_range(v, 2, 7) == 6
@assert count_in_range(v, 0, 100) == 8
@assert count_in_range(Int[], 0, 1) == 0
@assert try count_in_range(v, 5, 1); false catch e; e isa ArgumentError end
```

Two binary searches give the boundaries in O(log n), so the count never touches the elements in between. `searchsortedfirst(v, lo)` is the first index with `v[i] >= lo` and `searchsortedlast(v, hi)` the last with `v[i] <= hi`; an empty range such as `3:2` has length zero, which handles the no-match case without a branch. The argument check fails fast on a reversed range instead of silently returning 0.

```julia
function kth_smallest(v::AbstractVector, k::Integer)
    1 <= k <= length(v) || throw(ArgumentError("k = $k out of range 1:$(length(v))"))
    return partialsort(v, k)
end

# Checks
@assert kth_smallest([7, 2, 9, 4, 1], 1) == 1
@assert kth_smallest([7, 2, 9, 4, 1], 3) == 4
@assert kth_smallest([7, 2, 9, 4, 1], 5) == 9
v = [5, 4, 3]
kth_smallest(v, 2)
@assert try kth_smallest([1, 2], 3); false catch e; e isa ArgumentError end
```

`partialsort` does a selection-style partial sort in roughly O(n + k log k) and copies its input, so the caller's vector is unchanged (use `partialsort!` to allow reordering). Checking `k` first turns a confusing internal error into an `ArgumentError` naming the valid range.

```julia
top_k(xs, k::Integer) = partialsort!(collect(xs), 1:min(k, length(xs)); rev = true)

# Checks
@assert top_k([4, 9, 1, 7, 3], 3) == [9, 7, 4]
@assert top_k([4, 9], 5) == [9, 4]
@assert top_k(Int[], 2) == Int[]
@assert top_k((x^2 for x in 1:10), 2) == [100, 81]
```

`partialsort!` with a range sorts only the requested prefix, avoiding a full O(n log n) sort. `collect` makes a private copy so generators and the caller's vectors are both fine, and `min(k, length(xs))` makes oversized `k` return everything.

```julia
people = [(name = "Cy", score = 80), (name = "Al", score = 95), (name = "Bo", score = 80), (name = "Di", score = 95)]

ranked = sort(people; by = p -> (-p.score, p.name))

# Checks
@assert [p.name for p in ranked] == ["Al", "Di", "Bo", "Cy"]
@assert ranked == sort(people; lt = (a, b) -> a.score > b.score || (a.score == b.score && a.name < b.name))
@assert issorted(ranked; by = p -> (-p.score, p.name))
```

`by` maps each element to a key and tuples compare lexicographically, so negating the numeric field gives descending order for that field only. For non-numeric descending keys use `lt` or sort in two stable passes. `sort` returns a new vector; `sort!` would reorder `people` in place.

```julia
function two_sum(v::AbstractVector{<:Number}, target::Number)
    seen = Dict{eltype(v),Int}()
    for i in eachindex(v)
        j = get(seen, target - v[i], nothing)
        j === nothing || return (j, i)
        seen[v[i]] = i
    end
    return nothing
end

# Checks
@assert two_sum([2, 7, 11, 15], 9) == (1, 2)
@assert two_sum([3, 2, 4], 6) == (2, 3)
@assert two_sum([1, 2, 3], 10) === nothing
@assert two_sum(Int[], 1) === nothing
```

A `Dict` from value to index lets each element look up its complement in expected O(1), giving O(n) total. Looking up before inserting means an element is never paired with itself, while duplicates like `[3, 3]` still work. The dict is typed with `eltype(v)` so it is concrete.

```julia
function max_window_sum(v::AbstractVector{<:Number}, k::Integer)
    1 <= k <= length(v) || throw(ArgumentError("window size k = $k must be in 1:$(length(v))"))
    s = sum(@view v[begin:begin+k-1])
    best = s
    for i in firstindex(v)+k:lastindex(v)
        s += v[i] - v[i-k]
        best = max(best, s)
    end
    return best
end

# Checks
@assert max_window_sum([1, 4, 2, 10, 2, 3, 1, 0, 20], 4) == 24
@assert max_window_sum([-3, -1, -2], 2) == -3
@assert max_window_sum([0.5, 0.25, 1.0], 2) == 1.25
@assert try max_window_sum([1, 2], 3); false catch e; e isa ArgumentError end
```

Each step adds the entering element and subtracts the leaving one, so the whole scan is O(n) rather than O(nk). Starting from the first window's real sum (not zero) means all-negative inputs are handled correctly. For floating-point data, running add/subtract can accumulate rounding error on very long inputs.

```julia
struct PrefixSums{T<:Number}
    cum::Vector{T}   # cum[1] == 0, cum[i+1] == sum of the first i elements

    function PrefixSums(v::AbstractVector{<:Number})
        cum = cumsum(v)
        pushfirst!(cum, zero(eltype(cum)))
        return new{eltype(cum)}(cum)
    end
end

function range_sum(p::PrefixSums, l::Integer, r::Integer)
    1 <= l <= r + 1 && r <= length(p.cum) - 1 || throw(ArgumentError("invalid range $l:$r"))
    return p.cum[r+1] - p.cum[l]
end

# Checks
p = PrefixSums([3, 1, 4, 1, 5, 9])
@assert range_sum(p, 1, 6) == 23
@assert range_sum(p, 3, 2) == 0     # empty range
@assert range_sum(PrefixSums([0.5, 0.25]), 1, 2) == 0.75
@assert try range_sum(p, 1, 7); false catch e; e isa ArgumentError end
```

Storing `cum[1] = 0` followed by running totals makes any range sum a single subtraction, `cum[r+1] - cum[l]`, after O(n) preprocessing. The leading zero removes the special case for ranges starting at 1, and `cumsum` promotes small integer types, so the element type `T` is whatever `cumsum` produced.

```julia
function dedup_sorted!(v::AbstractVector)
    isempty(v) && return 0
    w = firstindex(v)
    for i in firstindex(v)+1:lastindex(v)
        if !isequal(v[i], v[w])
            w += 1
            v[w] = v[i]
        end
    end
    return w - firstindex(v) + 1
end

# Checks
a = [1, 1, 2, 2, 2, 3, 5, 5]
n = dedup_sorted!(a)
@assert n == 4 && a[1:n] == [1, 2, 3, 5]
@assert dedup_sorted!(Int[]) == 0
b = [4, 4, 4]
@assert dedup_sorted!(b) == 1 && b[1] == 4
@assert dedup_sorted!(["a", "a", "b"]) == 2
```

A write pointer `w` trails the read pointer `i`, so duplicates are overwritten in one pass with no extra memory. The vector's tail beyond the returned length is left unspecified, which is why the length is returned; use `resize!(v, n)` or `unique!` if you want the vector itself shortened.

```julia
function zeros_to_end!(v::AbstractVector{<:Number})
    w = firstindex(v)
    for x in v
        if !iszero(x)
            v[w] = x
            w += 1
        end
    end
    for i in w:lastindex(v)
        v[i] = zero(eltype(v))
    end
    return v
end

# Checks
@assert zeros_to_end!([0, 1, 0, 3, 12]) == [1, 3, 12, 0, 0]
@assert zeros_to_end!([0, 0]) == [0, 0]
@assert zeros_to_end!(Float64[]) == Float64[]
@assert zeros_to_end!([0.0, 2.5]) == [2.5, 0.0]
```

Compacting the non-zeros forward and then filling the tail with `zero(eltype(v))` is stable, O(n), and works for any numeric element type. Iterating `for x in v` while writing to earlier positions is safe here because the write index never passes the read position.

```julia
rotate_cw(A::AbstractMatrix) = reverse(permutedims(A); dims = 2)
rotate_ccw(A::AbstractMatrix) = reverse(permutedims(A); dims = 1)

# Checks
A = [1 2 3; 4 5 6; 7 8 9]
@assert rotate_cw(A) == [7 4 1; 8 5 2; 9 6 3]
@assert rotate_ccw(A) == [3 6 9; 2 5 8; 1 4 7]
@assert rotate_cw(rotate_cw(rotate_cw(rotate_cw(A)))) == A
B = [1 2 3; 4 5 6]
@assert rotate_cw(B) == [4 1; 5 2; 6 3]
```

A clockwise rotation is a transpose followed by reversing each row; the counterclockwise one reverses the rows after transposing. Both work for non-square matrices, since `permutedims` simply swaps the dimensions. Base provides `rotr90` and `rotl90`, which do the same without the intermediate allocation.

```julia
function matmul(A::AbstractMatrix, B::AbstractMatrix)
    size(A, 2) == size(B, 1) || throw(DimensionMismatch("inner dimensions differ: $(size(A)) * $(size(B))"))
    T = promote_type(eltype(A), eltype(B))
    C = zeros(T, size(A, 1), size(B, 2))
    for j in axes(B, 2), k in axes(A, 2), i in axes(A, 1)
        C[i, j] += A[i, k] * B[k, j]
    end
    return C
end

# Checks
A = [1 2; 3 4; 5 6]
B = [7 8 9; 10 11 12]
@assert matmul(A, B) == A * B
@assert matmul(rand(Int8, 3, 3), rand(Int8, 3, 3)) isa Matrix{Int8}
@assert matmul(Rational{Int}[1//2 1//3], [6; 6;;]) == [5//1;;]
@assert try matmul(ones(2, 3), ones(2, 3)); false catch e; e isa DimensionMismatch end
```

Julia arrays are column-major, so the innermost loop runs over the first index (`i`), making both `C[i, j]` and `A[i, k]` contiguous in memory; the `j, k, i` order is the cache-friendly one for this kernel. The accumulator type is the promotion of the inputs, which keeps `Int8` inputs `Int8` (and thus wraparound-prone) just like `*` does. For performance on `Float64` and friends, `A * B` calls BLAS.

```julia
identity_matrix(n::Integer) = [i == j ? 1.0 : 0.0 for i in 1:n, j in 1:n]
hilbert(n::Integer) = [1 / (i + j - 1) for i in 1:n, j in 1:n]
vandermonde(x::AbstractVector, deg::Integer) = [xi^j for xi in x, j in 0:deg]

# Checks
using LinearAlgebra
@assert identity_matrix(3) == I(3)
@assert hilbert(2) == [1.0 0.5; 0.5 1/3]
@assert size(vandermonde(1:4, 3)) == (4, 4)
@assert vandermonde(Int[], 2) == zeros(Int, 0, 3)
```

A two-index comprehension `[f(i, j) for i in ..., j in ...]` builds a matrix directly with the element type inferred from `f`. In `vandermonde`, `xi^j` keeps integers integers, and the columns are powers 0 to `deg`. Base's `I(n)` is a lazy identity that is usually better than a materialized one.

```julia
transposed(A::AbstractMatrix) = [A[j, i] for i in axes(A, 2), j in axes(A, 1)]

function is_symmetric(A::AbstractMatrix)
    axes(A, 1) == axes(A, 2) || return false
    return all(A[i, j] == A[j, i] for j in axes(A, 2) for i in first(axes(A, 1)):j)
end

# Checks
A = [1 2 3; 4 5 6]
@assert transposed(A) == [1 4; 2 5; 3 6]
@assert transposed(transposed(A)) == A
@assert transposed(A) == permutedims(A)
@assert is_symmetric([1.0 NaN; NaN 1.0]) == false
```

Using `axes` rather than `1:size(A, d)` keeps the functions correct for offset arrays: the transpose swaps the axes, and the symmetry test requires the row and column axes to be identical. Only the upper triangle is compared. With `NaN` entries `==` is false, so a matrix containing `NaN` is not reported symmetric; use `isequal` if you want `NaN` to match itself.

```julia
hamming(a::Integer, b::Integer) = count_ones(a ⊻ b)

function hamming(a::AbstractString, b::AbstractString)
    length(a) == length(b) || throw(ArgumentError("strings must have equal length, got $(length(a)) and $(length(b))"))
    return count(splat(!=), zip(a, b))
end

# Checks
@assert hamming(0b1011101, 0b1001001) == 2
@assert hamming("karolin", "kathrin") == 3
@assert hamming(UInt8(255), UInt8(0)) == 8
@assert try hamming("ab", "abc"); false catch e; e isa ArgumentError end
```

For integers the differing bits are the set bits of the XOR. For strings, `zip` pairs characters and `count(splat(!=), ...)` counts mismatches without building an intermediate array; `length` on strings counts characters, so Unicode is compared by character. Equal length is required by the definition, so it is checked.

```julia
function digital_root(s::AbstractString)
    all(isdigit, s) && !isempty(s) || throw(ArgumentError("expected a non-empty string of digits"))
    n = sum(c - '0' for c in s)
    return n < 10 ? n : digital_root(string(n))
end

# Checks
@assert digital_root("942") == 6
n = 987654321987654321
@assert digital_root(string(n)) == 1 + (n - 1) % 9
@assert try digital_root(""); false catch e; e isa ArgumentError end
@assert try digital_root("12a"); false catch e; e isa ArgumentError end
```

Summing the digit characters (`c - '0'` gives an integer) works on strings of any length, so there is no need to parse a huge number. The digital root also equals `1 + (n - 1) mod 9` for positive `n`, used in the test as an independent check. Validation rejects empty or non-digit input explicitly.

```julia
function sum_multiples(n::Integer)
    n >= 0 || throw(ArgumentError("n must be non-negative"))
    tri(k) = (m = (n - 1) ÷ k; k * m * (m + 1) ÷ 2)
    return tri(3) + tri(5) - tri(15)
end

# Checks
@assert sum_multiples(10) == 23
@assert sum_multiples(0) == 0 && sum_multiples(1) == 0
@assert all(n -> sum_multiples(n) == sum(k for k in 1:n-1 if k % 3 == 0 || k % 5 == 0; init = 0), 0:300)
@assert sum_multiples(10^9) == 233333333166666668
```

The multiples of k below n form an arithmetic series k(1 + 2 + ... + m) with m = floor((n-1)/k); inclusion-exclusion subtracts the multiples of 15 counted twice. That makes the answer O(1) regardless of n. Passing a `BigInt` works because nothing in the formula is tied to a fixed-width integer.

```julia
function lagrange(xs::AbstractVector, ys::AbstractVector, x)
    axes(xs) == axes(ys) || throw(DimensionMismatch("xs and ys must have the same axes"))
    allunique(xs) || throw(ArgumentError("xs must be distinct"))
    total = zero(float(promote_type(eltype(ys), typeof(x))))
    for i in eachindex(xs, ys)
        term = ys[i]
        for j in eachindex(xs)
            j == i && continue
            term *= (x - xs[j]) / (xs[i] - xs[j])
        end
        total += term
    end
    return total
end

# Checks
@assert lagrange([0, 1, 2], [1, 3, 7], 3) ≈ 13               # y = x^2 + x + 1
@assert lagrange([1, 2], [1.0f0, 2.0f0], 1.5f0) isa Float32
@assert try lagrange([1, 1], [1, 2], 0); false catch e; e isa ArgumentError end
@assert try lagrange([1, 2], [1], 0); false catch e; e isa DimensionMismatch end
```

Each term is the data value times a product that equals 1 at its own node and 0 at the others, so the polynomial passes exactly through all points. Distinct `xs` are required or the denominators vanish. The method is O(n^2) per evaluation and numerically fragile for many equally spaced nodes (Runge's phenomenon), so keep the degree modest.

```julia
function logsumexp(x::AbstractVector{<:Real})
    isempty(x) && return -Inf
    m = maximum(x)
    isinf(m) && return float(m)
    return m + log(sum(v -> exp(v - m), x))
end

softmax(x::AbstractVector{<:Real}) = exp.(x .- logsumexp(x))

# Checks
@assert logsumexp([1000.0, 1000.0]) ≈ 1000 + log(2)
@assert log(sum(exp, [1000.0, 1000.0])) == Inf               # naive version overflows
@assert softmax([1.0, 2.0, 3.0]) ≈ exp.([1.0, 2.0, 3.0]) ./ sum(exp, [1.0, 2.0, 3.0])
@assert eltype(softmax(Float32[1, 2])) == Float32
```

Subtracting the maximum before exponentiating keeps every exponent at most 0, so `exp` cannot overflow, and the largest term contributes exactly 1 so the sum cannot underflow to zero. The identity `softmax(x) = exp(x - logsumexp(x))` reuses the stable routine. The infinite-maximum guard avoids computing `Inf - Inf`.

```julia
function my_quantile(x::AbstractVector{<:Real}, p::Real)
    isempty(x) && throw(ArgumentError("x must be non-empty"))
    0 <= p <= 1 || throw(ArgumentError("p must be in [0, 1], got $p"))
    s = sort(x)
    pos = 1 + p * (length(s) - 1)
    lo = floor(Int, pos)
    hi = min(lo + 1, length(s))
    return s[lo] + (pos - lo) * (s[hi] - s[lo])
end

# Checks
using Statistics
x = [7.0, 1.0, 3.0, 9.0, 5.0, 2.0]
for p in (0, 0.1, 0.25, 0.5, 0.9, 1)
    @assert my_quantile(x, p) ≈ quantile(x, p)
end
@assert my_quantile([1, 2, 3, 4], 0.5) == 2.5
@assert try my_quantile([1, 2], 1.5); false catch e; e isa ArgumentError end
@assert try my_quantile(Int[], 0.5); false catch e; e isa ArgumentError end
```

The p-th quantile sits at fractional position `1 + p(n-1)` in the sorted data; interpolating between the neighboring order statistics reproduces `Statistics.quantile`'s default method, which the loop confirms. The `min` keeps the upper neighbor in range when p = 1. In practice call `quantile` directly.

```julia
using Random, Statistics

function bootstrap_mean_ci(x::AbstractVector{<:Real}; nboot::Integer = 2000, level::Real = 0.95, rng::AbstractRNG = Xoshiro(1))
    isempty(x) && throw(ArgumentError("x must be non-empty"))
    0 < level < 1 || throw(ArgumentError("level must be in (0, 1)"))
    means = [mean(rand(rng, x, length(x))) for _ in 1:nboot]
    α = (1 - level) / 2
    return quantile(means, (α, 1 - α))
end

# Checks
x = [4.1, 5.2, 6.3, 5.0, 4.8, 5.9, 6.1, 5.5, 4.9, 5.3]
lo, hi = bootstrap_mean_ci(x; rng = Xoshiro(42))
@assert lo < mean(x) < hi
@assert (lo, hi) == bootstrap_mean_ci(x; rng = Xoshiro(42))
@assert bootstrap_mean_ci(fill(3.0, 5)) == (3.0, 3.0)
@assert try bootstrap_mean_ci(Float64[]); false catch e; e isa ArgumentError end
```

Resampling the data with replacement many times and taking percentiles of the resampled means approximates the sampling distribution of the mean without distributional assumptions. `rand(rng, x, n)` draws n elements with replacement. The RNG is explicit for reproducibility.

```julia
using Random, Statistics

function mc_integrate(f, a::Real, b::Real, n::Integer; rng::AbstractRNG = Xoshiro(0))
    n >= 2 || throw(ArgumentError("need at least two samples"))
    vals = [f(a + (b - a) * rand(rng)) for _ in 1:n]
    return (b - a) * mean(vals), (b - a) * std(vals) / sqrt(n)
end

# Checks
est, se = mc_integrate(sin, 0, pi, 100_000; rng = Xoshiro(3))
@assert abs(est - 2) < 4se
@assert mc_integrate(x -> 1.0, 2, 5, 10) == (3.0, 0.0)
@assert mc_integrate(sin, 0, 1, 50; rng = Xoshiro(9)) == mc_integrate(sin, 0, 1, 50; rng = Xoshiro(9))
@assert try mc_integrate(sin, 0, 1, 1); false catch e; e isa ArgumentError end
```

The integral is the interval length times the mean of f at uniform random points, and the standard error is the sample standard deviation divided by sqrt(n), so the error falls as 1/sqrt(n) regardless of dimension. The test accepts results within four standard errors of the true value. Returning the error estimate along with the value tells the caller how much to trust it.

```julia
struct Polynomial{T<:Number}
    coeffs::Vector{T}              # coeffs[k] multiplies x^(k-1); no trailing zeros except for the zero polynomial
    function Polynomial{T}(c::AbstractVector) where {T<:Number}
        v = T.(c)
        while length(v) > 1 && iszero(last(v))
            pop!(v)
        end
        isempty(v) && push!(v, zero(T))
        new{T}(v)
    end
end
Polynomial(c::AbstractVector{T}) where {T<:Number} = Polynomial{T}(c)

degree(p::Polynomial) = length(p.coeffs) - 1
(p::Polynomial)(x) = evalpoly(x, p.coeffs)

function Base.:+(p::Polynomial, q::Polynomial)
    n = max(length(p.coeffs), length(q.coeffs))
    pad(c) = vcat(c, zeros(eltype(c), n - length(c)))
    return Polynomial(pad(p.coeffs) .+ pad(q.coeffs))
end

function Base.:*(p::Polynomial, q::Polynomial)
    r = zeros(promote_type(eltype(p.coeffs), eltype(q.coeffs)), degree(p) + degree(q) + 1)
    for (i, a) in enumerate(p.coeffs), (j, b) in enumerate(q.coeffs)
        r[i+j-1] += a * b
    end
    return Polynomial(r)
end

function Base.show(io::IO, p::Polynomial)
    terms = String[]
    for (k, c) in Iterators.reverse(collect(enumerate(p.coeffs)))
        iszero(c) && degree(p) > 0 && continue
        e = k - 1
        push!(terms, e == 0 ? string(c) : e == 1 ? "$(c)x" : "$(c)x^$e")
    end
    print(io, join(terms, " + "))
end

# Checks
p = Polynomial([1, 2, 3])               # 1 + 2x + 3x^2
q = Polynomial([0, 1])                  # x
@assert p(2) == 17
@assert degree(p) == 2 && degree(Polynomial([5, 0, 0])) == 0
@assert (p + Polynomial([-1, -2, -3])).coeffs == [0]
@assert repr(Polynomial([0, 0, 4])) == "4x^2"
```

The inner constructor trims trailing zero coefficients so each polynomial has one canonical representation and `degree` is meaningful. Making the type callable via `(p::Polynomial)(x)` lets it be used wherever a function is expected, and `evalpoly` does Horner evaluation. Full-featured polynomials are in the Polynomials package.

```julia
@enum Suit clubs diamonds hearts spades
@enum Rank two=2 three four five six seven eight nine ten jack queen king ace

struct Card
    rank::Rank
    suit::Suit
end

Base.isless(a::Card, b::Card) = (a.rank, a.suit) < (b.rank, b.suit)
Base.show(io::IO, c::Card) = print(io, c.rank, " of ", c.suit)

deck() = [Card(r, s) for s in instances(Suit) for r in instances(Rank)]

# Checks
d = deck()
@assert length(d) == 52 && allunique(d)
@assert maximum(d) == Card(ace, spades) && minimum(d) == Card(two, clubs)
@assert issorted(sort(d))
@assert repr(Card(queen, hearts)) == "queen of hearts"
