```julia
function repl_loop(input::IO, output::IO; evaluate = line -> Meta.parse(line) |> safe_eval)
    for line in eachline(input)
        s = strip(line)
        isempty(s) && continue
        s in ("quit", "exit") && break
        try
            println(output, evaluate(s))
        catch e
            e isa Union{ArgumentError,DomainError,DivideError,Meta.ParseError} || rethrow()
            println(output, "error: ", sprint(showerror, e))
        end
    end
    return nothing
end

# Only numbers, + - * / ^ and parentheses are evaluated; anything else is rejected.
function safe_eval(ex)
    ex isa Number && return ex
    if ex isa Expr && ex.head === :call && ex.args[1] in (:+, :-, :*, :/, :^) && length(ex.args) in (2, 3)
        return getfield(Base, ex.args[1])(map(safe_eval, ex.args[2:end])...)
    end
    throw(ArgumentError("unsupported expression: $ex"))
end

# Checks
function session(text)
    out = IOBuffer()
    repl_loop(IOBuffer(text), out)
    return split(String(take!(out)), '\n'; keepempty = false)
end
@assert session("1 + 2\n2 * (3 + 4)\n") == ["3", "14"]
@assert session("2^10\n-5 + 2\n\n7 / 2") == ["1024", "-3", "3.5"]
@assert startswith(only(session("run(`ls`)")), "error: ArgumentError: unsupported")
@assert only(session("x + 1")) == "error: ArgumentError: unsupported expression: x"
```

Parsing with `Meta.parse` and then walking the expression tree, accepting only numbers and a whitelist of arithmetic operators, evaluates user input without ever calling `eval`, so shell commands and function calls are refused. The evaluator is an argument, which keeps `repl_loop` testable and reusable. Only the expected exception types are caught; anything else propagates.

