```julia
function edit_distance(a::AbstractString, b::AbstractString)
    s, t = collect(a), collect(b)
    length(t) > length(s) && ((s, t) = (t, s))   # t is the shorter one
    prev = collect(0:length(t))
    cur = similar(prev)
    for i in eachindex(s)
        cur[1] = i
        for j in eachindex(t)
            cost = s[i] == t[j] ? 0 : 1
            cur[j+1] = min(prev[j+1] + 1, cur[j] + 1, prev[j] + cost)
        end
        prev, cur = cur, prev
    end
    return prev[end]
end

# Checks
@assert edit_distance("kitten", "sitting") == 3
@assert edit_distance("same", "same") == 0
@assert edit_distance("flaw", "lawn") == 2
@assert edit_distance("café", "cafe") == 1
```

Each cell depends only on the previous row and the cell to its left, so two vectors replace the full table and the shorter string sets their length. Insert, delete, and substitute all cost 1. Work is O(mn) time; collecting to `Char` vectors makes `é` count as a single edit.

```julia
function knapsack(weights::AbstractVector{<:Integer}, values::AbstractVector{<:Real}, capacity::Integer)
    axes(weights) == axes(values) || throw(DimensionMismatch("weights and values must have the same axes"))
    capacity >= 0 || throw(ArgumentError("capacity must be non-negative, got $capacity"))
    best = zeros(promote_type(eltype(values), Int), capacity + 1)
    for (w, v) in zip(weights, values)
        w >= 0 || throw(ArgumentError("weights must be non-negative"))
        for c in capacity:-1:w
            best[c+1] = max(best[c+1], best[c-w+1] + v)
        end
    end
    return best[end]
end

# Checks
@assert knapsack([1, 3, 4, 5], [1, 4, 5, 7], 7) == 9
@assert knapsack([2, 3], [1.5, 2.5], 5) == 4.0
@assert knapsack([1, 1, 1], [1, 1, 1], 0) == 0
@assert try knapsack([1], [1, 2], 3); false catch e; e isa DimensionMismatch end
```

`best[c+1]` is the best value achievable with capacity `c`. Looping capacities downward for each item guarantees each item is used at most once, which is what makes this 0/1 rather than unbounded. Time is O(n x capacity) and memory O(capacity). The value array's element type is promoted from the values so floats are not truncated.

