function lis_length(v::AbstractVector)
    tails = eltype(v)[]
    for x in v
        i = searchsortedfirst(tails, x)
        i > length(tails) ? push!(tails, x) : (tails[i] = x)
    end
    return length(tails)
end

# Checks
@assert lis_length([10, 9, 2, 5, 3, 7, 101, 18]) == 4
@assert lis_length([1, 1, 1]) == 1
@assert lis_length([5, 4, 3]) == 1
@assert lis_length([0.5, 0.1, 0.9]) == 2
```

`tails[k]` is the smallest possible last element of an increasing subsequence of length k+1, and it stays sorted, so each element is placed with a binary search via `searchsortedfirst`. Using the first position with `tails[i] >= x` gives strictly increasing subsequences; use `searchsortedlast` plus one for non-decreasing ones. Time is O(n log n).

