function fib_memo(n::Integer)
    n >= 0 || throw(ArgumentError("n must be non-negative, got $n"))
    memo = Dict{Int,BigInt}(0 => 0, 1 => 1)
    function f(k)
        get!(memo, k) do
            f(k - 1) + f(k - 2)
        end
    end
    return f(n)
end

# Checks
