function primes_upto(n::Integer)
    n < 2 && return Int[]
    isprime = trues(n)
    isprime[1] = false
    for p in 2:isqrt(n)
        isprime[p] || continue
        for m in p*p:p:n
            isprime[m] = false
        end
    end
    return findall(isprime)
end

