```julia
function fib(n::Integer)
    n >= 0 || throw(ArgumentError("n must be non-negative, got $n"))
    function pair(k)               # returns (F(k), F(k+1))
        k == 0 && return (big(0), big(1))
        a, b = pair(k >> 1)
        c = a * (2b - a)           # F(2m)
        d = a * a + b * b          # F(2m+1)
        return iseven(k) ? (c, d) : (d, c + d)
    end
    return first(pair(n))
end

# Checks
