function divisor_sum(n::Integer)
    n >= 1 || throw(ArgumentError("n must be positive"))
    s = zero(n)
    for d in 1:isqrt(n)
        q, r = divrem(n, d)
        r == 0 || continue
        s += d
        q != d && (s += q)
    end
    return s
end

is_perfect(n::Integer) = n > 1 && divisor_sum(n) == 2n

