function word_freq(text::AbstractString, n::Integer = 3)
    counts = Dict{String,Int}()
    for m in eachmatch(r"\p{L}+", text)
        w = lowercase(m.match)
        counts[w] = get(counts, w, 0) + 1
    end
    ranked = sort!(collect(counts); by = p -> (-last(p), first(p)))
    return first(ranked, n)
end

