function balanced(s::AbstractString)
    pairs_ = Dict(')' => '(', ']' => '[', '}' => '{')
    stack = Char[]
    for c in s
        if c in values(pairs_)
            push!(stack, c)
        elseif haskey(pairs_, c)
            (!isempty(stack) && pop!(stack) == pairs_[c]) || return false
        end
    end
    return isempty(stack)
end

# Checks
