function char_histogram(s::AbstractString)
    counts = Dict{Char,Int}()
    for c in s
        counts[c] = get(counts, c, 0) + 1
    end
    return sort!(collect(counts); by = p -> (-last(p), first(p)))
end

# Checks
@assert char_histogram("mississippi") == ['i' => 4, 's' => 4, 'p' => 2, 'm' => 1]
@assert char_histogram("") == Pair{Char,Int}[]
@assert char_histogram("ééa") == ['é' => 2, 'a' => 1]
@assert sum(last, char_histogram("hello world")) == 11
```

A `Dict{Char,Int}` accumulates counts in one pass. Sorting by `(-count, char)` makes ties deterministic. For a known small alphabet a fixed-size count vector would be faster, but a `Dict` handles all of Unicode without assumptions.

```julia
function camel_to_snake(s::AbstractString)
    out = replace(s, r"(?<=[a-z0-9])(?=[A-Z])" => "_")
    return lowercase(out)
end

function snake_to_camel(s::AbstractString)
    parts = split(s, '_'; keepempty = false)
    isempty(parts) && return ""
    return string(lowercase(first(parts)), map(p -> uppercasefirst(lowercase(p)), parts[2:end])...)
end

# Checks
@assert camel_to_snake("myVariableName") == "my_variable_name"
@assert camel_to_snake("already_snake") == "already_snake"
@assert snake_to_camel("my_variable_name") == "myVariableName"
@assert snake_to_camel(camel_to_snake("parseHttpRequest")) == "parseHttpRequest"
```

The lookbehind/lookahead pattern inserts an underscore at each lower-to-upper boundary without consuming characters. Going the other way, `split` with `keepempty = false` ignores leading, trailing, and doubled underscores. Runs of capitals such as `HTTPServer` are not split specially.

```julia
is_decimal(s::AbstractString) = occursin(r"^[+-]?(\d+(\.\d*)?|\.\d+)$", s)

# Checks
@assert is_decimal("42")
@assert is_decimal("-3.14")
@assert !is_decimal("1.2.3")
@assert is_decimal("3.5") && parse(Float64, "3.5") == 3.5
```

The anchors `^` and `$` force the whole string to match, and the alternation handles `7.` and `.5` while rejecting a bare `.`. When you only need the number, `tryparse(Float64, s)` returns `nothing` instead of throwing and is usually the better choice; it also accepts exponents and `Inf`.

