using Random

function random_walk(n::Integer; rng::AbstractRNG = Random.default_rng())
    n >= 0 || throw(ArgumentError("n must be non-negative"))
    steps = rand(rng, (-1, 1), n)
    return pushfirst!(cumsum(steps), 0)
end

# Checks
w1 = random_walk(1000; rng = Xoshiro(42))
w2 = random_walk(1000; rng = Xoshiro(42))
@assert w1 == w2                               # same seed, same walk
@assert length(w1) == 1001 && w1[1] == 0
@assert w1 != random_walk(1000; rng = Xoshiro(43))
@assert random_walk(0; rng = Xoshiro(1)) == [0]
```

Passing the RNG explicitly makes results reproducible and independent of other code that uses the global generator. Drawing all steps at once with `rand(rng, (-1, 1), n)` and taking `cumsum` is much simpler than a loop and does one allocation. The start position 0 is prepended so the walk has n + 1 points.

```julia
poly_eval(coeffs, x) = evalpoly(x, coeffs)

function poly_deriv_coeffs(coeffs::AbstractVector)
    length(coeffs) <= 1 && return zero(coeffs)[1:min(1, end)]
    return [(k - 1) * coeffs[k] for k in firstindex(coeffs)+1:lastindex(coeffs)]
end

# Checks
p = [1, 2, 3]                       # 1 + 2x + 3x^2
@assert poly_eval(p, 2) == 17
@assert poly_eval(p, 1 + 1im) == 1 + 2 * (1 + 1im) + 3 * (1 + 1im)^2
@assert poly_eval(poly_deriv_coeffs(p), 2) == 14
@assert evalpoly(2, (1, 2, 3)) == 17         # tuples unroll at compile time
```

`evalpoly` uses Horner's scheme, which needs n multiplications and is more accurate than summing powers; it takes the coefficients in ascending order and works for any numeric `x`, including complex values. For a derivative the coefficient of `x^(k-2)` is `(k-1) * c_k`, with indices starting at one. A tuple of coefficients lets the compiler unroll the evaluation.

