using Statistics

function summarize(x::AbstractVector{<:Real})
    isempty(x) && throw(ArgumentError("cannot summarize an empty vector"))
    return (n = length(x), mean = mean(x), std = length(x) > 1 ? std(x) : zero(float(eltype(x))),
            median = median(x), extrema = extrema(x))
end

# Checks
s = summarize([2, 4, 4, 4, 5, 5, 7, 9])
@assert s.n == 8 && s.mean == 5.0 && s.median == 4.5 && s.extrema == (2, 9)
@assert summarize([3.0]).std == 0.0
@assert summarize([1, 2, 3, 4]).median == 2.5
