flatten(x) = x isa AbstractVector ? reduce(vcat, (flatten(y) for y in x); init = Any[]) : Any[x]

function flatten_typed(x)
    out = Any[]
    walk(y) = y isa AbstractVector ? foreach(walk, y) : push!(out, y)
    walk(x)
    return identity.(out)
