```julia
function runs(v::AbstractVector)
    out = Tuple{eltype(v),Int}[]
    for x in v
        if !isempty(out) && isequal(first(last(out)), x)
            out[end] = (x, last(last(out)) + 1)
        else
            push!(out, (x, 1))
        end
    end
    return out
end

# Checks
