Base.iterate(c::Collatz) = (c.start, c.start)
function Base.iterate(::Collatz{T}, n::T) where {T}
    n == 1 && return nothing
    n = iseven(n) ? n ÷ T(2) : T(3) * n + one(T)
    return (n, n)
end
Base.IteratorSize(::Type{<:Collatz}) = Base.SizeUnknown()
Base.eltype(::Type{Collatz{T}}) where {T} = T

