```julia
struct Permutations{T}
    items::Vector{T}
end

Base.length(p::Permutations) = factorial(length(p.items))
Base.eltype(::Type{Permutations{T}}) where {T} = Vector{T}

function Base.iterate(p::Permutations, st = nothing)
    n = length(p.items)
    if st === nothing
        return (copy(p.items), (copy(p.items), ones(Int, n), 1))
    end
    a, c, i = st
    while i <= n
        if c[i] < i
            j = isodd(i) ? 1 : c[i]
            a[i], a[j] = a[j], a[i]
            c[i] += 1
            return (copy(a), (a, c, 2))
        end
        c[i] = 1
        i += 1
    end
    return nothing
end

# Checks
