@assert length(ps) == 6 && length(unique(ps)) == 6
@assert Set(ps) == Set([[1, 2, 3], [2, 1, 3], [3, 1, 2], [1, 3, 2], [2, 3, 1], [3, 2, 1]])
@assert length(collect(Permutations(collect('a':'e')))) == 120
@assert sum(1 for _ in Permutations(collect(1:7))) == 5040
