The outer constructor promotes mixed arguments so `Point(1, 2.5)` becomes a `Point{Float64}` instead of a `MethodError`. Defining `zero` for the type lets `sum` work on a vector of points, and `hypot` avoids overflow in the norm. Using a single type parameter `T` for both fields keeps the layout concrete and efficient.

```julia
function fizzbuzz(n::Integer)
    n >= 0 || throw(ArgumentError("n must be non-negative"))
    return map(1:n) do i
        i % 15 == 0 ? "FizzBuzz" : i % 3 == 0 ? "Fizz" : i % 5 == 0 ? "Buzz" : string(i)
    end
end

# Checks
@assert fizzbuzz(15)[[3, 5, 15, 7]] == ["Fizz", "Buzz", "FizzBuzz", "7"]
@assert fizzbuzz(0) == String[]
@assert count(==("FizzBuzz"), fizzbuzz(100)) == 6
@assert length(fizzbuzz(30)) == 30
```

Checking divisibility by 15 first avoids the double-hit ordering bug. `map` over a range with a `do` block returns a concretely typed `Vector{String}`, and the function returns data instead of printing, so it is testable; print with `foreach(println, fizzbuzz(20))`.

```julia
function power_set(v::AbstractVector{T}) where {T}
    n = length(v)
    n <= 20 || throw(ArgumentError("refusing to build 2^$n subsets"))
    return [T[v[i] for i in eachindex(v) if (mask >> (i - firstindex(v))) & 1 == 1] for mask in 0:(1<<n)-1]
end

# Checks
ps = power_set([1, 2, 3])
@assert length(ps) == 8
@assert Set(ps) == Set([[], [1], [2], [3], [1, 2], [1, 3], [2, 3], [1, 2, 3]])
@assert length(power_set(collect('a':'j'))) == 1024
@assert try power_set(1:25); false catch e; e isa ArgumentError end
```

Each integer from 0 to 2^n - 1 encodes one subset: bit `i` says whether element `i` is included. Preserving the original order inside each subset comes free. The size guard fails fast on inputs where the answer would not fit in memory.

```julia
const ROMAN = [1000 => "M", 900 => "CM", 500 => "D", 400 => "CD", 100 => "C", 90 => "XC",
               50 => "L", 40 => "XL", 10 => "X", 9 => "IX", 5 => "V", 4 => "IV", 1 => "I"]

function to_roman(n::Integer)
    1 <= n <= 3999 || throw(ArgumentError("Roman numerals cover 1:3999, got $n"))
    io = IOBuffer()
    for (value, sym) in ROMAN
        while n >= value
            print(io, sym)
            n -= value
        end
    end
    return String(take!(io))
end

function from_roman(s::AbstractString)
    vals = Dict('I' => 1, 'V' => 5, 'X' => 10, 'L' => 50, 'C' => 100, 'D' => 500, 'M' => 1000)
    isempty(s) && throw(ArgumentError("empty string"))
    all(c -> haskey(vals, c), s) || throw(ArgumentError("invalid Roman numeral: $s"))
    v = [vals[c] for c in s]
    return sum(i < length(v) && v[i] < v[i+1] ? -v[i] : v[i] for i in eachindex(v))
end

# Checks
@assert to_roman(1994) == "MCMXCIV"
@assert to_roman(4) == "IV" && to_roman(3999) == "MMMCMXCIX"
@assert try to_roman(0); false catch e; e isa ArgumentError end
@assert try from_roman("ABC"); false catch e; e isa ArgumentError end
```

A descending table that includes the subtractive pairs (`CM`, `IV`, ...) lets a greedy loop produce the canonical form. Reading backwards, a symbol smaller than its right neighbor is subtracted. The table is a `const`, so access is type-stable.

```julia
const ONES = ["zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten",
              "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"]
const TENS = ["", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]

function in_words(n::Integer)
    0 <= n < 1_000_000 || throw(ArgumentError("n must be in 0:999999, got $n"))
    n < 20 && return ONES[n+1]
    n < 100 && return TENS[n÷10+1] * (n % 10 == 0 ? "" : "-" * ONES[n%10+1])
    n < 1000 && return ONES[n÷100+1] * " hundred" * (n % 100 == 0 ? "" : " and " * in_words(n % 100))
    rest = n % 1000
    return in_words(n ÷ 1000) * " thousand" * (rest == 0 ? "" : rest < 100 ? " and " * in_words(rest) : " " * in_words(rest))
end

# Checks
@assert in_words(0) == "zero"
@assert in_words(342) == "three hundred and forty-two"
@assert in_words(999_999) == "nine hundred and ninety-nine thousand nine hundred and ninety-nine"
@assert try in_words(10^6); false catch e; e isa ArgumentError end
```

Recursion on the decomposition into thousands, hundreds, and the remaining 0..99 keeps each case short, and lookup tables give 1-based access to the word for `k` as `table[k+1]`. British "and" placement is used. The range check at the top guards the table lookups.

```julia
function is_armstrong(n::Integer)
    d = digits(n)
    return n == sum(x -> x^length(d), d)
end

# Checks
@assert is_armstrong(153) && is_armstrong(9474) && is_armstrong(5)
@assert !is_armstrong(154)
@assert filter(is_armstrong, 100:999) == [153, 370, 371, 407]
@assert filter(is_armstrong, 1:9999) == [1, 2, 3, 4, 5, 6, 7, 8, 9, 153, 370, 371, 407, 1634, 8208, 9474]
```

A number is Armstrong if the sum of its digits each raised to the number of digits equals the number itself. Computing `digits` once, rather than converting to a string, avoids parsing and keeps the code integer-only. For very large n the digit powers could overflow `Int`; convert with `big` first in that case.

```julia
missing_letters(s::AbstractString) = sort!(collect(setdiff('a':'z', lowercase(s))))
is_pangram(s::AbstractString) = isempty(missing_letters(s))

# Checks
@assert is_pangram("The quick brown fox jumps over the lazy dog")
@assert missing_letters("abc") == collect('d':'z')
@assert is_pangram("Pack my box with five dozen liquor jugs!")
@assert missing_letters("The quick brown fox jumps over the lazy dog") == Char[]
```

`setdiff` of the alphabet range with the lowercased string returns the letters not present, and the pangram test is just emptiness of that set. Non-letters in the input are ignored automatically because they are not in `'a':'z'`. Time is O(26 + n).

```julia
function wins(n::Integer; moves = (1, 2, 3))
    n >= 0 || throw(ArgumentError("n must be non-negative"))
    win = falses(n + 1)                     # win[k+1]: player to move wins with k stones
    for k in 1:n
        win[k+1] = any(m -> m <= k && !win[k-m+1], moves)
    end
    return win[n+1]
end

# Checks
@assert [wins(n) for n in 0:9] == [false, true, true, true, false, true, true, true, false, true]
@assert wins(7) && !wins(8)
@assert all(n -> wins(n) == (n % 4 != 0), 0:100)
@assert wins(5; moves = (2, 5)) && !wins(1; moves = (2, 5))
```

A position is winning if some move leads to a losing position for the opponent, which is a bottom-up table fill over 0..n stones. With moves 1-3 the losing positions are exactly the multiples of 4, which the test confirms against the table. Iterating upwards avoids recursion depth limits.

```julia
function eval_rpn(expr::AbstractString)
    ops = Dict{String,Function}("+" => +, "-" => -, "*" => *, "/" => /, "^" => ^)
    stack = Float64[]
    for tok in split(expr)
        if haskey(ops, tok)
            length(stack) >= 2 || throw(ArgumentError("operator $tok needs two operands"))
            b = pop!(stack); a = pop!(stack)
            push!(stack, ops[tok](a, b))
        else
            x = tryparse(Float64, tok)
            x === nothing && throw(ArgumentError("invalid token \"$tok\""))
            push!(stack, x)
        end
    end
    length(stack) == 1 || throw(ArgumentError("malformed expression: $(length(stack)) values left"))
    return only(stack)
end

# Checks
@assert eval_rpn("3 4 + 2 *") == 14
@assert try eval_rpn("1 +"); false catch e; e isa ArgumentError end
@assert try eval_rpn("1 2"); false catch e; e isa ArgumentError end
@assert try eval_rpn("1 x +"); false catch e; e isa ArgumentError end
```

A stack evaluates postfix in one pass: numbers are pushed, an operator pops two operands (right one first) and pushes the result. Mapping token strings to Base functions in a `Dict` makes adding an operator a one-line change. Every malformed case is checked and reported rather than leaving a stray value or a `BoundsError`.

```julia
function parse_duration(s::AbstractString)
    m = match(r"^(\d+):([0-5]\d):([0-5]\d)$", s)
    m === nothing && throw(ArgumentError("expected HH:MM:SS, got \"$s\""))
    h, mi, se = parse.(Int, m.captures)
    return 3600h + 60mi + se
end

function format_duration(secs::Integer)
    secs >= 0 || throw(ArgumentError("duration must be non-negative"))
    h, r = divrem(secs, 3600)
    m, s = divrem(r, 60)
    return string(lpad(h, 2, '0'), ':', lpad(m, 2, '0'), ':', lpad(s, 2, '0'))
end

# Checks
@assert parse_duration("01:02:03") == 3723
@assert all(format_duration(parse_duration(format_duration(n))) == format_duration(n) for n in (0, 59, 60, 3599, 86399, 123456))
@assert try parse_duration("1:75:00"); false catch e; e isa ArgumentError end
@assert try parse_duration("abc"); false catch e; e isa ArgumentError end
```

The regex restricts minutes and seconds to 00-59 while allowing any number of hour digits, so validation and splitting happen in one step. `divrem` extracts hours, minutes and seconds without separate division and modulus. For calendar work, use the `Dates` standard library instead.

```julia
function parse_people(s::AbstractString)
    people = Dict{String,Int}()
    for (i, entry) in enumerate(split(s, ';'; keepempty = false))
        parts = split(entry, ':')
        length(parts) == 2 || throw(ArgumentError("entry $i (\"$entry\"): expected name:age"))
        age = tryparse(Int, parts[2])
        (age === nothing || age < 0) && throw(ArgumentError("entry $i (\"$entry\"): invalid age \"$(parts[2])\""))
        people[strip(parts[1])] = age
    end
    return people
end

# Checks
@assert parse_people("ann:31;bob:27") == Dict("ann" => 31, "bob" => 27)
@assert try parse_people("ann"); false catch e; e isa ArgumentError && occursin("entry 1", e.msg) end
@assert try parse_people("ann:1;bob:x"); false catch e; e isa ArgumentError && occursin("entry 2", e.msg) end
@assert try parse_people("ann:-3"); false catch e; e isa ArgumentError end
```

`split` with `keepempty = false` ignores stray separators, and `tryparse` avoids exceptions for ordinary bad input while the function still reports the position and text of the offending entry. All failures raise `ArgumentError`, so callers have one exception type to handle.

```julia
to_hex(s::AbstractString) = join(string(b, base = 16, pad = 2) for b in codeunits(s))

function from_hex(h::AbstractString)
    iseven(length(h)) || throw(ArgumentError("hex string must have even length"))
    bytes = [parse(UInt8, h[i:i+1]; base = 16) for i in 1:2:length(h)]
    return String(bytes)
end

# Checks
@assert to_hex("Hi!") == "486921"
@assert from_hex(to_hex("naïve ☃")) == "naïve ☃"
@assert try from_hex("abc"); false catch e; e isa ArgumentError end
@assert try from_hex("zz"); false catch e; e isa ArgumentError end
```

`codeunits` exposes the UTF-8 bytes of a string without copying, so multibyte characters become several hex pairs. `string(b, base = 16, pad = 2)` zero-pads to two digits. Odd-length input is rejected up front, and `parse` raises `ArgumentError` for non-hex digits. For production use there is also `bytes2hex` and `hex2bytes` in Base.

