using Base64

encode(s::AbstractString) = base64encode(s)
decode(s::AbstractString) = String(base64decode(s))

# Checks
@assert encode("Hello, World!") == "SGVsbG8sIFdvcmxkIQ=="
@assert decode("SGVsbG8sIFdvcmxkIQ==") == "Hello, World!"
